-- Changelog: project- en medewerkerplanning vullen het scherm, één scrollgebied.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-01','verbeterd','Planning','Planning vult het scherm, met één scrollbalk',
   'De projectplanning en de medewerkerplanning gebruiken nu het hele scherm. Je scrolt nog maar op één plek in plaats van in twee vlakken door elkaar, en de balk met de dagen en weken blijft bovenin staan terwijl je door de lijst naar beneden gaat. De kolom met namen blijft links staan als je naar rechts schuift. Ook is de bovenkant compacter gemaakt, zodat er een paar regels meer in beeld passen.');
